const { Card, List, Tag, Empty, Typography, Segmented, Space, Spin } = ctx.libs.antd;

const TIME_SLOTS = [
  { key: 1, label: '第1节', start: '08:30', end: '10:10' },
  { key: 2, label: '第2节', start: '10:30', end: '12:10' },
  { key: 3, label: '第3节', start: '14:00', end: '15:40' },
  { key: 4, label: '第4节', start: '16:00', end: '17:40' },
  { key: 5, label: '晚间', start: '19:00', end: '20:40' },
];
const DAY_LABELS = ['周一', '周二', '周三', '周四', '周五', '周六', '周日'];
const KIND_TAGS = { topic: ['专题课', 'blue'], activity: ['活动', 'orange'], video: ['视频课', 'cyan'], elective: ['选修', 'purple'] };

function slotOf(t) {
  const hhmm = bjHhmm(t);
  const hit = TIME_SLOTS.find((s) => hhmm >= s.start && hhmm < s.end);
  if (hit) return hit.key;
  const next = TIME_SLOTS.find((s) => hhmm < s.start);
  return next ? next.key : TIME_SLOTS.length;
}

function bjHhmm(t) {
  if (!t) return '';
  const d = new Date(new Date(t).getTime() + 8 * 3600 * 1000);
  const p = (n) => String(n).padStart(2, '0');
  return p(d.getUTCHours()) + ':' + p(d.getUTCMinutes());
}

function rowsOf(res) {
  const d = res?.getData?.();
  if (Array.isArray(d)) return d;
  return d?.data || [];
}

async function load() {
  ctx.render(<Card size="small"><div style={{ textAlign: 'center', padding: 24 }}><Spin /> <Typography.Text>课程表加载中…</Typography.Text></div></Card>);

  let classes = [];
  try {
    const classRes = ctx.makeResource('MultiRecordResource');
    classRes.setResourceName('nb_dx_class');
    classRes.setPageSize(20);
    await classRes.refresh();
    classes = rowsOf(classRes);
  } catch (e) {
    classes = [];
  }
  if (!classes.length) {
    ctx.render(<Card size="small"><Empty description="未找到本班班次信息" /></Card>);
    return;
  }
  const klass = classes[0];

  let rows = [];
  let teachers = [];
  try {
    const schRes = ctx.makeResource('MultiRecordResource');
    schRes.setResourceName('nb_dx_course_schedule');
    schRes.setPageSize(200);
    schRes.setFilter({ class_id: klass.id });
    await schRes.refresh();
    rows = rowsOf(schRes);

    const tRes = ctx.makeResource('MultiRecordResource');
    tRes.setResourceName('nb_dx_teacher');
    tRes.setPageSize(200);
    await tRes.refresh();
    teachers = rowsOf(tRes);
  } catch (e) {
    ctx.render(<Card size="small"><Empty description={'课表加载失败：' + (e?.message || e)} /></Card>);
    return;
  }
  const teacherName = {};
  for (const t of teachers) teacherName[t.id] = t.name;

  if (!rows.length) {
    ctx.render(<Card size="small" title={'我的课程表 · ' + klass.name}><Empty description="暂无排课" /></Card>);
    return;
  }
  const weeks = [...new Set(rows.map((r) => Number(r.week_no) || 1))].sort((a, b) => a - b);
  let curWeek = weeks[0];
  const self = { redraw: null };

  const drawWeek = () => {
    const weekRows = rows.filter((r) => (Number(r.week_no) || 1) === curWeek);
    const dayCards = DAY_LABELS.map((label, i) => {
      const items = weekRows
        .filter((r) => (Number(r.day_of_week) || 1) === i + 1)
        .sort((a, b) => bjHhmm(a.start_time).localeCompare(bjHhmm(b.start_time)));
      if (!items.length) return null;
      return (
        <Card key={label} size="small" title={label} style={{ marginBottom: 8 }}>
          <List
            size="small"
            dataSource={items}
            renderItem={(it) => {
              const kind = KIND_TAGS[it.kind];
              const slotDef = TIME_SLOTS[slotOf(it.start_time) - 1];
              const time = slotDef.label + ' ' + slotDef.start + '–' + slotDef.end;
              const teacher = teacherName[it.teacher_id] ? ' · ' + teacherName[it.teacher_id] : '';
              return (
                <List.Item>
                  <List.Item.Meta
                    title={<Space wrap><Typography.Text strong>{it.topic_name}</Typography.Text>{kind ? <Tag color={kind[1]}>{kind[0]}</Tag> : null}</Space>}
                    description={time + teacher + (it.place ? ' · ' + it.place : '')}
                  />
                </List.Item>
              );
            }}
          />
        </Card>
      );
    });
    const hasAny = dayCards.some(Boolean);
    ctx.render(
      <Card
        size="small"
        title={'我的课程表 · ' + klass.name}
        extra={
          weeks.length > 1 ? (
            <Segmented
              size="small"
              options={weeks.map((w) => ({ label: '第' + w + '周', value: w }))}
              value={curWeek}
              onChange={(v) => { curWeek = v; self.redraw && self.redraw(); }}
            />
          ) : null
        }
      >
        {hasAny ? dayCards : <Empty description="该周暂无排课" />}
      </Card>
    );
  };
  self.redraw = drawWeek;
  drawWeek();
}

await load();
